function TrailStageChallengeCell:__init()
    self.btnAction = nil

end

function TrailStageChallengeCell:__delete()
    self.btnAction = nil

    self.controller = nil
end

---SetCallBack
---设置单击回调函数
function TrailStageChallengeCell:SetBtnCallBack(cb)
    self.btnAction = cb
end

function TrailStageChallengeCell:Awake()
    trailBattleMgr = TrailBattleMgr:GetInstance()
    UIEventProxy.Create(self.controller.gameObject).onPointerClick = function()
        if type(self.btnAction) == 'function' then
            self.btnAction()
        end
    end
end

function TrailStageChallengeCell:FreshBaseUI(questId, luaIndex)
    local isLock = not trailBattleMgr:IsUnlockQuest(luaIndex)
    KTool.SetActive(self.Normal, not isLock)
    KTool.SetActive(self.Lock, isLock)
    if isLock then
        local text
        if luaIndex == 3 then
            text = "最强王者"
        else
            text = "黄金"
        end
        self.TextLock.text = string.format("%s段位解锁", text)
    else
        CfUtils.PlayAnimator(self.Fight, "Go")
        self.TextIndex.text = "#"..luaIndex
        --region 敌人
        local allLineVo = QuestConfMgr:GetInstance():GetAllQuestLineupVo(questId)
        local teamMemberData = {}
        for k, v in pairs(allLineVo) do
            local monsterList = v.wave1NpcId
            for i, b in pairs(monsterList) do
                local monsterData = {}
                local monsterTypeData = CfUtils.GetCfVo(AutoIds.IdSetting39, "MonsterTypeVo", b)
                if monsterTypeData.role > 0 then
                    local cardData = CardConfMgr:GetCardByRefId(monsterTypeData.mode)
                    monsterData["id"] = b
                    monsterData["defaultSkin"] = monsterTypeData.skinId
                    monsterData["rare"] = cardData.rare
                else
                    monsterData["id"] = b
                    monsterData["defaultSkin"] = monsterTypeData.skinId
                    monsterData["rare"] = monsterTypeData.monsterClass
                end
                table.insert(teamMemberData, monsterData)
            end
        end
        local enemyLayoutEnv = CfUtils.GetLuaScr(self.LayoutEnemy, "Game.UI.TrailStage.TrailStageChallengeTeamLayout")
        if enemyLayoutEnv then
            enemyLayoutEnv:FreshEnemyTeam(teamMemberData)
        end
        --endregion
        --region 自己
        local data = teamComponent:GetTeamInfoByQuestId(questId, luaIndex)
        self.TextPower.text = teamComponent:GetTeamFightingPower(data.cardsInfo)
        --print("teamNum---->>"..(QuestConfMgr:GetInstance():GetQuestTeamNum(questId)))
        --print("teamData---->>"..table.dump(data, nil, 3))
        local myTeamLayoutEnv = CfUtils.GetLuaScr(self.LayoutMe, "Game.UI.TrailStage.TrailStageChallengeTeamLayout")
        if myTeamLayoutEnv then
            myTeamLayoutEnv:FreshMyTeam
            (
                    data.cardsInfo,
                    function()
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamCardChoose, parameters = {levelId = questId, teamIndex = luaIndex}}, {
                            {id = Constants.UITypeIds.TrailStageMain},
                            {id = Constants.UITypeIds.TrailStageChallenge},
                        })
                    end
            )
        end
        --endregion
    end
end




